using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using SurfaceSafety;

// Desktop layout simulation only: base S24 pixel dimensions, assumed insets and density.
// No model invocation, device connection, or persisted connection-setting change occurs.
public static class S24LayoutVerification {
    const int Width=1080, Height=2340, Top=90, Bottom=72;
    const float Density=3f, Minimum=48f*Density;
    static string Output=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../outputs/milestone1/s24"));
    [Serializable] class Check {public string name;public bool passed;}
    [Serializable] class Control {
        public string screen,name;public float x,y,widthPx,heightPx,widthDp,heightDp;
        public bool withinSafeArea,meets48dp,partiallyClippedByScroll,interactable;
    }
    [Serializable] class TextMetric {public string screen,label,role;public int configuredSize;public float renderedFontPx,assumedDpEquivalent,requiredDp;public bool meetsMinimum;}
    [Serializable] class Report {
        public string status="passed_with_findings",device="Samsung Galaxy S24 (base)",orientation="portrait",renderType="Unity desktop render; not a device screenshot";
        public int width=Width,height=Height,assumedTopInset=Top,assumedBottomInset=Bottom;
        public float assumedDensity=Density,minimumTouchDp=48;
        public string assumptions="90 px top / 72 px bottom insets and density 3 are assumed gesture-navigation test settings, not measured One UI configuration. Insets injected into the actual safeRoot immediately before capture.";
        public string qwenProvenance="Saved genuine qwen-response-13.json; replayed through ApplyResponse, not generated by this layout test. See source file hash and modification timestamp for provenance.";
        public string qwenResponseSha256,qwenResponseModifiedUtc;
        public string untested="Physical touch, Android keyboard, system gesture conflicts, camera tracking, thermal/performance and actual S24 safe area remain untested.";
        public int functionalChecks,functionalPassed,controlChecks,controlsWithinSafeArea,controlsMeeting48dp;
        public int textChecks,textMeetingMinimum;public TextMetric[] text;public Check[] checks;public Control[] controls;public string[] findings,screens;
    }
    static readonly List<Check> checks=new List<Check>();
    static readonly List<Control> controls=new List<Control>();
    static readonly List<TextMetric> textMetrics=new List<TextMetric>();
    static readonly List<string> screens=new List<string>();
    static void CheckThat(bool value,string name){checks.Add(new Check{name=name,passed=value});}
    static Button FindButton(string name)=>UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None)
        .First(b=>b.gameObject.activeInHierarchy&&(b.name==name||(b.GetComponentInChildren<Text>()!=null&&b.GetComponentInChildren<Text>().text==name)));
    static void Click(string name){FindButton(name).onClick.Invoke();}
    static Rect Bounds(RectTransform r,Camera camera){
        var corners=new Vector3[4];r.GetWorldCorners(corners);
        var points=corners.Select(p=>RectTransformUtility.WorldToScreenPoint(camera,p)).ToArray();
        return Rect.MinMaxRect(points.Min(p=>p.x),points.Min(p=>p.y),points.Max(p=>p.x),points.Max(p=>p.y));
    }
    static Rect Intersection(Rect a,Rect b)=>Rect.MinMaxRect(Mathf.Max(a.xMin,b.xMin),Mathf.Max(a.yMin,b.yMin),Mathf.Min(a.xMax,b.xMax),Mathf.Min(a.yMax,b.yMax));
    public static void Run(){
        checks.Clear();controls.Clear();textMetrics.Clear();screens.Clear();Directory.CreateDirectory(Output);
        EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
        var host=new GameObject("S24 layout simulation");var boot=host.AddComponent<SceneBootstrap>();boot.previewMode=true;boot.Initialize();
        var replay=boot.Replay;var client=host.GetComponent<QwenReasoningClient>();
        client.Configure("http://127.0.0.1:8765",""); // Show no local token in artifact; do not save settings.
        var camera=Camera.main;var target=new RenderTexture(Width,Height,24);camera.targetTexture=target;camera.aspect=(float)Width/Height;SceneBootstrap.FramePreview(camera);
        var safe=(RectTransform)typeof(StandReplay).GetField("safeRoot",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(replay);
        var safeBounds=new Rect(0,Bottom,Width,Height-Top-Bottom);
        Action<string,string> capture=(name,provenance)=>{
            var canvases=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);
            foreach(var canvas in canvases){canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=.1f;}
            safe.anchorMin=new Vector2(0,(float)Bottom/Height);safe.anchorMax=new Vector2(1,1f-(float)Top/Height);
            safe.offsetMin=safe.offsetMax=Vector2.zero;
            Canvas.ForceUpdateCanvases();
            // Initial CanvasScaler rebuild can trigger the runtime safe-area refresh. Reapply
            // the test profile after that rebuild, before measurement and render.
            safe.anchorMin=new Vector2(0,(float)Bottom/Height);safe.anchorMax=new Vector2(1,1f-(float)Top/Height);
            Canvas.ForceUpdateCanvases();
            int topOrder=canvases.Max(c=>c.sortingOrder);
            foreach(var selectable in UnityEngine.Object.FindObjectsByType<Selectable>(FindObjectsSortMode.None)){
                if(!selectable.gameObject.activeInHierarchy||selectable.GetComponentInParent<Canvas>().sortingOrder!=topOrder)continue;
                var rect=Bounds((RectTransform)selectable.transform,camera);var visible=rect;
                foreach(var mask in selectable.GetComponentsInParent<RectMask2D>())visible=Intersection(visible,Bounds(mask.rectTransform,camera));
                if(visible.width<=0||visible.height<=0)continue;
                bool clipped=Math.Abs(rect.height-visible.height)>1||Math.Abs(rect.width-visible.width)>1;
                controls.Add(new Control{screen=name,name=selectable.name,x=rect.x,y=rect.y,widthPx=rect.width,heightPx=rect.height,widthDp=rect.width/Density,heightDp=rect.height/Density,
                    withinSafeArea=visible.xMin>=safeBounds.xMin-1&&visible.xMax<=safeBounds.xMax+1&&visible.yMin>=safeBounds.yMin-1&&visible.yMax<=safeBounds.yMax+1,
                    meets48dp=rect.width>=Minimum-1&&rect.height>=Minimum-1,partiallyClippedByScroll=clipped,interactable=selectable.IsInteractable()});
            }
            foreach(var label in UnityEngine.Object.FindObjectsByType<Text>(FindObjectsSortMode.None)){
                if(!label.gameObject.activeInHierarchy||label.GetComponentInParent<Canvas>().sortingOrder!=topOrder)continue;
                if(label.GetComponentInParent<InputField>()!=null&&label.GetComponentInParent<InputField>().contentType==InputField.ContentType.Password)continue;
                var bounds=Bounds(label.rectTransform,camera);var visible=bounds;
                foreach(var mask in label.GetComponentsInParent<RectMask2D>())visible=Intersection(visible,Bounds(mask.rectTransform,camera));
                if(visible.width<=0||visible.height<=0||string.IsNullOrWhiteSpace(label.text))continue;
                var owner=label.GetComponentInParent<Selectable>();
                bool main=label.fontSize>=39||(owner!=null&&owner.GetComponentsInChildren<Text>().Length==1);
                float pixels=label.fontSize*label.GetComponentInParent<Canvas>().scaleFactor;
                textMetrics.Add(new TextMetric{screen=name,label=label.text.Length>100?label.text.Substring(0,100):label.text,role=main?"main/action":"secondary",configuredSize=label.fontSize,renderedFontPx=pixels,assumedDpEquivalent=pixels/Density,requiredDp=main?14:12,meetsMinimum=pixels/Density>=(main?14:12)-.05f});
            }
            camera.Render();RenderTexture.active=target;var image=new Texture2D(Width,Height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,Width,Height),0,0);image.Apply();
            File.WriteAllBytes(Path.Combine(Output,name+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);screens.Add(name+".png");
        };
        const string preview="Galaxy S24 layout simulation · assumed insets · not a device screenshot";
        replay.SelectAircraft(1);replay.Seek(14);replay.SelectTab("now");capture("s24-now",preview);
        Click("History");CheckThat(replay.SelectedTab=="history","History navigation button");
        CheckThat(replay.VisibleReports.All(e=>e.flightInstance=="F2-R1"),"History preserves selected flight identity");
        capture("s24-history",preview);
        Click("E03");CheckThat(replay.InspectedReportId=="E03","Report row opens E03 details");capture("s24-report-detail",preview);
        Click("Jump to receipt · 14 s");CheckThat(Math.Abs(replay.Clock.Time-14)<.001f&&!replay.Clock.Playing,"Report jump uses receipt time and pauses");
        Click("‹  Reports");CheckThat(replay.InspectedReportId=="","Report back button returns to history");
        Click("Now");Click("Latest change");CheckThat(replay.SelectedTab=="history"&&replay.InspectedReportId=="E03","Latest-update card opens source report");
        replay.Seek(13);CheckThat(!replay.VisibleReports.Any(e=>e.id=="E03")&&replay.InspectedReportId!="E03","Rewind hides unavailable late report and its detail");
        Click("Why");CheckThat(replay.SelectedTab=="why","Why navigation button");
        var responseFile=Path.GetFullPath(Path.Combine(Output,"../qwen-response-13.json"));var response=JsonUtility.FromJson<ReasoningResponse>(File.ReadAllText(responseFile));
        var request=new ReasoningRequest{requestId=response.requestId,scenarioId=response.scenarioId,aircraftId=response.aircraftId,checkpoint=response.checkpoint};
        CheckThat(client.ApplyResponse(request,response),"Saved genuine response passes current local evidence check");
        capture("s24-qwen","Saved production response · 13 s · see source response JSON/audit");
        Click("Recorded facts");CheckThat(replay.CurrentReasoning.Contains("Overall readiness remains unknown"),"Deterministic baseline remains separately available");capture("s24-baseline",preview);
        Click("More");Click("Model connection");CheckThat(UnityEngine.Object.FindObjectsByType<InputField>(FindObjectsSortMode.None).Length==2,"Connection panel opens address and token fields");capture("s24-connection",preview);
        Click("Cancel");CheckThat(UnityEngine.Object.FindObjectsByType<InputField>(FindObjectsSortMode.None).Length==0,"Connection cancellation closes panel without saving");
        replay.Seek(30);replay.SelectTab("now");capture("s24-moving",preview);
        replay.previewMode=false;replay.Tracking(false);replay.Play();CheckThat(!replay.Clock.Playing&&!replay.Content.gameObject.activeSelf,"Tracking loss hides scene and blocks replay");
        capture("s24-tracking-lost",preview);
        replay.Tracking(true);CheckThat(!replay.Clock.Playing,"Tracking recovery does not auto-resume replay");
        var findings=new List<string>();
        if(controls.Any(c=>!c.withinSafeArea))findings.Add("One or more visible interactive controls exceed the assumed safe area; see controls.");
        if(controls.Any(c=>!c.meets48dp))findings.Add("Some controls are below 48 dp at the assumed density 3; see exact measured bounds. This is a usability finding, not a passed physical-touch test.");
        if(textMetrics.Any(t=>!t.meetsMinimum))findings.Add("Some labels fall below the assumed minimum type size; see text metrics.");
        findings.Add("Text metrics use Unity font size × canvas scale factor / assumed density 3; they are dp-equivalents, not measured Android sp. OS font scaling is untested.");
        findings.Add("Scroll-viewport clipping is intentional; only the visible portion is checked for safe-area containment.");
        findings.Add("Connection panel tested without keyboard. Keyboard avoidance and physical text input need device testing.");
        var report=new Report{status=checks.All(c=>c.passed)&&controls.All(c=>c.withinSafeArea)?"passed_with_findings":"failed",functionalChecks=checks.Count,functionalPassed=checks.Count(c=>c.passed),controlChecks=controls.Count,
            qwenResponseSha256=BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(responseFile))).Replace("-","").ToLowerInvariant(),qwenResponseModifiedUtc=File.GetLastWriteTimeUtc(responseFile).ToString("O"),controlsWithinSafeArea=controls.Count(c=>c.withinSafeArea),controlsMeeting48dp=controls.Count(c=>c.meets48dp),textChecks=textMetrics.Count,textMeetingMinimum=textMetrics.Count(t=>t.meetsMinimum),text=textMetrics.ToArray(),checks=checks.ToArray(),controls=controls.ToArray(),findings=findings.ToArray(),screens=screens.ToArray()};
        File.WriteAllText(Path.Combine(Output,"layout-verification.json"),JsonUtility.ToJson(report,true));
        camera.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(target);
        Debug.Log("S24_LAYOUT_VERIFICATION_COMPLETE: "+report.status+" / "+report.functionalPassed+" functional checks passed");
        if(report.status=="failed")throw new Exception("S24 layout verification failed; inspect layout-verification.json");
    }
}
